const svgAssets={home:'home-2-svgrepo-com.svg',search:'search-magnifier-ui-svgrepo-com.svg',shopping_bag:'shopping-bag-svgrepo-com.svg',inventory_2:'order-svgrepo-com.svg',receipt_long:'order-svgrepo-com.svg',person:'user-profile-avatar-svgrepo-com.svg',notifications:'bell-ui-notification-svgrepo-com.svg',location_on:'place-ui-pin-svgrepo-com.svg',favorite:'love-ui-heart-svgrepo-com.svg',recycling:'recycle-svgrepo-com.svg',agriculture:'agriculture-svgrepo-com.svg',local_shipping:'delivery-truck-van-svgrepo-com.svg',shopping_cart:'shopping-basket-svgrepo-com.svg',verified:'verified-check-svgrepo-com.svg',verified_user:'verified-check-svgrepo-com.svg'};
const icon=(name)=>svgAssets[name]?`<img class="symbol svg-asset asset-${name}" src="${svgAssets[name]}" alt="" aria-hidden="true">`:`<svg class="symbol" viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${iconPaths[name]||iconPaths.eco}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const userAvatar=()=>db.user?.photo?`<img class="avatar-image" src="${db.user.photo}" alt="${esc(db.user.name)}">`:esc(db.user?.avatar||'👩🏽‍🌾');
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2600)}
function notificationCount(){if(db.role==='staff')return db.submissions.filter(s=>s.status==='Submitted').length+db.orders.filter(o=>o.status==='Order received').length;if(db.role==='generator')return db.submissions.filter(s=>s.generator===db.user?.name&&!['Verified','Cancelled'].includes(s.status)).length;return db.orders.filter(o=>o.status==='Order received'||o.status==='Confirmed'||o.status==='On the way').length}
function notificationBell(){const count=notificationCount();return `${icon('notifications')}${count?`<i class="notification-count-badge">${count>99?'99+':count}</i>`:''}`}
function notifyUser(title,message){toast(message);if('Notification'in window&&Notification.permission==='granted'){try{new Notification(title,{body:message,icon:'eco-market-logo.png'})}catch(error){console.info('Browser notification could not be shown:',error)}}}
function notificationsPage(){const items=[];if(db.role==='staff'){db.submissions.forEach(s=>items.push({icon:'recycling',title:'Generator waste submitted',body:`${s.generator} submitted ${Number(s.qty).toLocaleString()} kg for pickup in ${s.location}.`,time:s.date,route:'stafforders',status:s.status}));db.orders.forEach(o=>items.push({icon:'receipt_long',title:'Farmer order received',body:`${o.receiverName||'A farmer'} ordered ${o.items.reduce((n,i)=>n+i.qty,0).toLocaleString()} kg · ${o.id}.`,time:o.date,route:'stafforders',status:o.status}))}else if(db.role==='generator'){db.submissions.filter(s=>s.generator===db.user.name).forEach(s=>items.push({icon:'recycling',title:s.status==='Submitted'?'Waste submitted successfully':`Pickup ${s.status.toLowerCase()}`,body:`${Number(s.qty).toLocaleString()} kg pickup request · ${s.location}.`,time:s.date,route:'trackwaste',status:s.status}))}else{db.orders.forEach(o=>items.push({icon:'local_shipping',title:o.status==='Order received'?'Order placed successfully':`Order ${o.status.toLowerCase()}`,body:`${o.id} · ${o.items.reduce((n,i)=>n+i.qty,0).toLocaleString()} kg · ${o.deliveryDate?'Delivery requested '+o.deliveryDate:'Delivery date pending'}.`,time:o.date,route:`tracking/${o.id}`,status:o.status}))}items.sort((a,b)=>String(b.time||'').localeCompare(String(a.time||'')));const head=db.role==='staff'?`<span>Operations workspace</span><strong>${esc(db.user.name)}</strong>`:db.role==='generator'?`<span>Notifications</span><strong>${icon('location_on')} ${esc(db.user.location||'Your collection area')}</strong>`:`<span>Notifications</span><strong>${icon('location_on')} ${esc(db.user?.location||'Your farm')}</strong>`;return `<div class="page farmer-home-page notifications-page"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Open profile">${userAvatar()}</button><div class="farmer-greeting-copy">${head}</div><span class="farmer-notifications notifications-current" aria-label="Notifications">${notificationBell()}</span></div></section><div class="notifications-content"><div class="page-heading"><div><div class="eyebrow">UPDATES</div><h1>Notifications</h1><p>Stay up to date with orders, pickups, and account activity.</p></div><span class="badge">${items.length} update${items.length===1?'':'s'}</span></div>${items.length?`<section class="notifications-list">${items.map(n=>`<button class="notification-card" data-go="${esc(n.route)}"><span class="notification-icon">${icon(n.icon)}</span><span class="notification-copy"><strong>${esc(n.title)}</strong><span>${esc(n.body)}</span><small>${esc(n.time||'Recently')} · ${esc(n.status)}</small></span>${icon('arrow_forward')}</button>`).join('')}</section>`:`<section class="notifications-empty card"><span class="notification-empty-icon">${icon('notifications')}</span><h2>You’re all caught up</h2><p>New order and pickup updates will show up here.</p></section>`}</div></div>`}
function go(route){if(route==='market'||route==='category'||route.startsWith('product/'))route='cart';location.hash=route;render()}
function login(role){db.role=role;db.user=role==='staff'?{name:'Amina N.',title:'Operations manager',avatar:'👩🏽‍💼',phone:'+256 700 123 456',email:'amina@greendivert.africa',location:'Kampala, Uganda'}:role==='generator'?{name:'Generator Demo',title:'Community waste generator',avatar:'♻️',phone:'+256 700 456 789',location:'Kampala'}:{name:'Christine',title:'BSF farmer · Wakiso',avatar:'👩🏽‍🌾'};save();go(role==='staff'?'staff':role==='generator'?'home':'home');toast(`Welcome ${db.user.name.split(' ')[0]}!`)}
const route=()=>location.hash.replace(/^#\/?/,'')|| (db.role==='staff'?'staff':'home');
function brand(){return `<div class="brand"><div class="brand-mark"><img class="brand-logo-crop" src="eco-market-logo.png" alt=""></div><div>ECO MARKET<small>CONNECT</small></div></div>`}
function brandLockup(size='auth'){return `<div class="brand-lockup ${size}"><div class="brand-emblem"><img src="eco-market-logo.png" alt="ECO MARKET CONNECT"></div></div>`}
const farmerNav=[['home','home','Home'],['tracking','local_shipping','Track delivery'],['profile','person','My farm']];
const generatorNav=[['home','home','Home'],['submissions','recycling','Submit waste'],['trackwaste','local_shipping','Track waste'],['profile','person','Profile']];
const staffNav=[['staff','space_dashboard','Overview'],['inventory','inventory_2','Inventory'],['collection','add_box','Log collection'],['stafforders','receipt_long','Orders'],['agents','groups','Field agents']];
function mobileNavigation(isStaff,active){const items=isStaff?staffNav:db.role==='generator'?generatorNav:[['home','home','Home'],['cart','shopping_bag','Order'],['tracking','local_shipping','Track']];const cartCount=db.cart.reduce((n,x)=>n+x.qty,0);return `<nav class="mobile-nav" aria-label="Main navigation">${items.map(([r,i,l])=>{const count=r==='cart'?cartCount:0;return `<button type="button" data-go="${r}" class="${active===r?'active':''} ${r==='cart'?'mobile-cart':''}" ${active===r?'aria-current="page"':''} aria-label="${l}${count?` (${count})`:''}">${r==='cart'?'<img class="nav-bag-svg" src="shopping-bag-svgrepo-com.svg" alt="">':icon(i)}${count?`<i class="nav-count order-count">${count>99?'99+':count}</i>`:''}<span>${l}</span></button>`}).join('')}</nav>`}
function shell(content){const isStaff=db.role==='staff',isGenerator=db.role==='generator',isGuest=!db.role,nav=isStaff?staffNav:isGenerator?generatorNav:isGuest?[]:farmerNav;const currentRoute=route(),active=currentRoute.startsWith('tracking/')?'tracking':currentRoute==='category'?'home':currentRoute.startsWith('product/')?'market':currentRoute;app.innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<nav class="side-nav">${nav.map(([r,i,l])=>`<button class="side-link ${active===r?'active':''}" data-go="${r}">${icon(i)}${l}</button>`).join('')}</nav><div class="side-bottom"><div class="side-help"><strong>Need a hand?</strong><p>Our team is here to help your farm grow.</p><button class="btn btn-soft btn-block" data-action="help">${icon('support_agent')} Contact support</button></div><div class="profile-mini"><button type="button" class="avatar" data-go="profile" aria-label="View profile">${userAvatar()}</button><div data-go="profile" style="cursor:pointer"><strong>${isGuest?'Browsing as guest':esc(db.user.name)}</strong><small>${isGuest?'Sign in when you place an order':esc(db.user.title)}</small></div>${isGuest?`<button class="btn btn-soft" style="margin-left:auto" data-action="existing-login">Sign in</button>`:`<button class="icon-btn" style="margin-left:auto" data-action="logout" aria-label="Sign out">${icon('logout')}</button>`}</div></div></aside><main class="main ${isStaff?'staff-mobile-interface':isGenerator?'generator-mobile-home':(['home','market','tracking','favorites','cart','profile'].includes(active)||active.startsWith('product/'))?'farmer-mobile-home':''}">${isStaff?`<section class="staff-mobile-head farmer-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="View staff profile">${userAvatar()}</button><div class="farmer-greeting-copy"><span>Operations workspace</span><strong>${esc(db.user.name)}</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${notificationBell()}</button></div></section>`:''}<header class="topbar"><div class="topbar-left"><button class="icon-btn hamburger" data-action="menu">${icon('menu')}</button><span class="mobile-brand">${brand()}</span><strong class="topbar-title">${isStaff?'Operations workspace':isGenerator?'Generator workspace':'Farmer workspace'}</strong></div><div class="topbar-right"><span class="badge" style="background:#eef8ee">${icon('wifi')} <span>Synced</span></span><button class="icon-btn" data-action="notifications" aria-label="Notifications">${notificationBell()}</button>${isGuest?`<button type="button" class="btn btn-soft" data-action="existing-login">Sign in</button>`:isStaff?`<button type="button" class="avatar" data-go="profile" aria-label="View staff profile" title="View profile">${userAvatar()}</button>`:`<button type="button" class="avatar" data-go="profile" aria-label="Edit profile">${userAvatar()}</button>`}</div></header>${content}${mobileNavigation(isStaff,active)}</main></div>`;startPromoCarousel();}
let onboardingStep=0,startupTimer=null;
const onboardingSlides=[{title:'Fresh feedstock for your farm',copy:'Find quality-checked organic waste collected for your BSF operation.'},{title:'Know what is available',copy:'Browse fresh collections from local markets and collection agents.'},{title:'Order and follow delivery',copy:'Place an order and keep up with every update until it reaches your farm.'}];
function renderOnboarding(){const slide=onboardingSlides[onboardingStep];app.innerHTML=`<main class="onboarding-screen"><div class="onboarding-green"><button class="onboarding-skip" data-onboarding="skip">Skip</button><div class="onboarding-farmer" aria-hidden="true"><span class="farmer-orbit orbit-a"></span><span class="farmer-orbit orbit-b"></span><svg class="farmer-memoji" viewBox="0 0 280 330" role="img" aria-label="Smiling farmer in a straw hat"><defs><linearGradient id="farmerShirt" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#63b96b"/><stop offset="1" stop-color="#17693b"/></linearGradient><linearGradient id="farmerHat" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#f8d36c"/><stop offset="1" stop-color="#cc8b32"/></linearGradient></defs><ellipse cx="140" cy="307" rx="87" ry="12" fill="#103c2860"/><path d="M50 305c5-62 37-96 90-96s86 34 90 96z" fill="url(#farmerShirt)"/><path d="M116 207h48v38c-13 15-35 15-48 0z" fill="#75452f"/><path d="M83 115c0-52 25-81 57-81s57 29 57 81v47c0 44-28 70-57 70s-57-26-57-70z" fill="#8e5738"/><path d="M84 129c6-31 20-50 34-59 20 15 45 19 78 15-6-35-29-55-59-55-39 0-65 33-65 86 0 18 4 32 11 45z" fill="#34291f"/><ellipse cx="105" cy="130" rx="8" ry="11" fill="#fff"/><ellipse cx="175" cy="130" rx="8" ry="11" fill="#fff"/><circle cx="107" cy="131" r="4.5" fill="#202820"/><circle cx="177" cy="131" r="4.5" fill="#202820"/><path d="M91 112q14-12 28 0m42 0q14-12 28 0" fill="none" stroke="#422e24" stroke-width="6" stroke-linecap="round"/><path d="M139 134q-2 19-10 27 9 7 19 0" fill="none" stroke="#72432f" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="M116 174q24 24 48 0" fill="none" stroke="#54291f" stroke-width="6" stroke-linecap="round"/><path d="M44 74q8-43 96-43 85 0 96 43-96 29-192 0Z" fill="url(#farmerHat)" stroke="#a9712d" stroke-width="4"/><path d="M64 76q76-23 152 0" fill="none" stroke="#ffe79b" stroke-width="5" stroke-linecap="round"/><path d="M112 216l28 34 28-34" fill="#f3f7e9"/><path d="m119 233 21 17-15 25-22-40m57 0-20 15 15 27 22-42" fill="#f3f7e9"/></svg><span class="farmer-leaf">${icon('agriculture')}</span></div><svg class="onboarding-wave" viewBox="0 0 100 34" preserveAspectRatio="none" aria-hidden="true"><path d="M0 2 Q50 54 100 2 L100 34 L0 34Z" fill="white"/></svg></div><div class="onboarding-content"><div class="onboarding-dots">${onboardingSlides.map((_,i)=>`<button class="${i===onboardingStep?'active':''}" data-onboarding-dot="${i}" aria-label="Page ${i+1}"></button>`).join('')}</div><span class="eyebrow">ECO MARKET CONNECT</span><h1>${slide.title}</h1><p>${slide.copy}</p><div class="onboarding-actions">${onboardingStep?`<button class="onboarding-back" data-onboarding="back">${icon('arrow_back')}</button>`:''}<button class="btn btn-primary" data-onboarding="next">${onboardingStep===onboardingSlides.length-1?'Let’s explore':'Continue'} ${icon('arrow_forward')}</button></div></div></main>`}
function finishOnboarding(){try{localStorage.setItem('gdfa-onboarded-v1','1')}catch{}go(db.role?(db.role==='staff'?'staff':'home'):'home')}
function startExperience(){const preview=new URLSearchParams(location.search);app.innerHTML=`<main class="splash-screen" role="status" aria-label="Loading ECO MARKET CONNECT"><span class="splash-orbit splash-orbit-one"></span><span class="splash-orbit splash-orbit-two"></span><div class="brand-lockup splash"><div class="brand-emblem"><img src="eco-market-logo.png" alt="ECO MARKET CONNECT"></div></div><p class="splash-tagline">Where green agriculture meets climate conservation through waste management</p><div class="splash-loader" aria-hidden="true"><i></i></div><small>Preparing your experience…</small></main>`;startupTimer=setTimeout(()=>{if(preview.get('login')==='1'){loginPage();return}let onboarded=false;try{onboarded=localStorage.getItem('gdfa-onboarded-v1')==='1'}catch{}if(preview.get('welcome')==='1'||!onboarded){onboardingStep=0;renderOnboarding();return}if(!db.role){loginPage();return}go(db.role==='staff'?'staff':'home')},6000)}
function loginPage(){app.innerHTML=`<div class="auth"><section class="auth-visual">${brandLockup('auth')}<div class="auth-quote"><div class="eyebrow">A smarter way to grow</div><h1>Trash To.<br>Cash  Circular Economy.</h1><p>Reliable organic feedstock for your farm, sourced from your community and delivered to your door.</p><div class="auth-stat"><div><strong>1,200+</strong><span>farmers growing</span></div><div><strong>8,400t</strong><span>waste diverted</span></div><div><strong>12 districts</strong><span>and growing</span></div></div></div><div class="auth-art">🌱♻️</div></section><section class="auth-panel"><div class="auth-form"><span class="eyebrow">Welcome back</span><h2>Good to see you.</h2><p>Choose your workspace to continue.</p><div class="demo-actions"><button type="button" class="btn btn-soft" onclick="startDemo('farmer')"> Farmer sign in</button><button type="button" class="btn btn-primary" onclick="startDemo('staff')"> Staff sign in</button><button type="button" class="btn btn-outline" onclick="startDemo('generator')">Generator demo</button></div><form id="login-form" class="auth-fields"><label class="field">Farmer phone number<input name="identity" required placeholder="e.g. +256 700 123 456" autocomplete="username"></label><label class="field">Password<input required type="password" placeholder="Enter your password" autocomplete="current-password"></label><div style="display:flex;justify-content:space-between;align-items:center;font-size:12px"><label><input type="checkbox" checked> Remember me</label><button type="button" class="text-link" data-action="forgot">Forgot password?</button></div><button class="btn btn-primary btn-block" type="submit">Sign in as farmer ${icon('arrow_forward')}</button></form><div class="auth-foot">New to ECO MARKET CONNECT? <button class="text-link" data-action="signup">Create farmer account</button></div></div></section></div>`}
function stat(label,val,ico,trend){return `<div class="card stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${val}</div><span class="trend">${trend}</span></div>`}
function wasteCard(w){return `<article class="card waste-card"><div class="waste-image ${w.color}" style="background-image:url('${imageFor(w.color)}')"><span class="tag">${icon('verified')} Quality checked</span></div><div class="waste-body"><div class="waste-title"><h3>${esc(w.name)}</h3>${icon('more_horiz')}</div><div class="muted tiny">Sorted organic waste · ${esc(w.location)}</div><div class="waste-meta"><span>${icon('scale')} ${w.stock.toLocaleString()} kg available</span><span>${icon('schedule')} ${esc(w.fresh)}</span></div><div style="display:flex;align-items:baseline;justify-content:space-between"><span class="price">${money(w.price)}<small> / ${esc(w.unit)}</small></span><span class="badge">In stock</span></div><button class="btn btn-soft btn-block" data-add="${w.id}">${icon('add_shopping_cart')} Add to order</button></div></article>`}
function imageFor(c){const imgs={vegetable:'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=900&q=82',banana:'https://images.unsplash.com/photo-1571771894821-ce9b6c11b08e?auto=format&fit=crop&w=900&q=82',maize:'https://images.unsplash.com/photo-1601593768796-54e1f9f1d080?auto=format&fit=crop&w=900&q=82',pineapple:'https://images.unsplash.com/photo-1550258987-190a2d41a8ba?auto=format&fit=crop&w=900&q=82',coffee:'https://images.unsplash.com/photo-1447933601403-0c6688de566e?auto=format&fit=crop&w=900&q=82',cassava:'https://images.unsplash.com/photo-1518977676601-b53f82aba655?auto=format&fit=crop&w=900&q=82'};return imgs[c]||imgs.vegetable}
function mobileWasteCard(w){return `<article class="mobile-waste-card"><div class="mobile-waste-image" style="background-image:url('${imageFor(w.color)}')"><span class="mobile-fresh">Fresh</span><button class="mobile-heart ${db.favorites.includes(w.id)?'saved':''}" data-favorite="${w.id}" aria-label="${db.favorites.includes(w.id)?'Remove from':'Add to'} favorites">${icon('favorite')}</button></div><div class="mobile-waste-info"><strong>${esc(w.name)}</strong><small>${esc(w.location.split(',')[0])} · ${w.stock.toLocaleString()} kg</small><div class="mobile-price-row"><b>${money(w.price)}</b><span>/ sack</span><button class="mobile-add" data-add="${w.id}" aria-label="Add ${esc(w.name)}">${icon('shopping_bag')}</button></div></div></article>`}
function categoryProductCard(w){return `<article class="category-product-card"><button class="category-product-open" data-go="product/${w.id}" aria-label="View ${esc(w.name)} details"><div class="category-product-image" style="background-image:url('${imageFor(w.color)}')"><span class="category-fresh">Fresh</span></div><div class="category-product-copy"><strong>${esc(w.name)}</strong><small>${esc(w.location.split(',')[0])} · ${w.stock.toLocaleString()} kg</small><div class="category-product-price"><b>${money(w.price)}</b><span>/ sack</span></div></div></button><button class="category-product-favorite ${db.favorites.includes(w.id)?'saved':''}" data-favorite="${w.id}" aria-label="Toggle favorite">${icon('favorite')}</button><button class="category-product-add" data-add="${w.id}" aria-label="Add ${esc(w.name)} to order">${icon('shopping_bag')}</button></article>`}
function homeSearchResults(q){const term=q.trim().toLowerCase();if(!term)return '';const matches=db.inventory.filter(w=>(`${w.name} ${w.location}`).toLowerCase().includes(term));return `<div class="home-search-results" role="listbox" aria-label="Search results">${matches.length?matches.slice(0,5).map(w=>`<button type="button" class="home-search-result" data-home-result="${w.id}"><img src="${imageFor(w.color)}" alt=""><span><strong>${esc(w.name)}</strong><small>Sorted organic waste · ${esc(w.location.split(',')[0])}</small></span><b>${money(w.price)}</b></button>`).join(''):`<div class="home-search-empty">${icon('search')}<span><strong>No matching supplies</strong><small>Try another search or location.</small></span></div>`}</div>`}
let promoTimer=null,promoTouchX=0;
function farmerPromo(forGenerator=false){const ads=[{kicker:'QUALITY CHECKED ORGANIC WASTE',title:'Reliable feedstock.<br>Ready for your BSF farm.',copy:'Sorted organic waste, checked for quality before it reaches your farm.',image:'hero-organic-waste.jpeg'},{kicker:'COLLECTED CLOSE TO YOU',title:'Good waste, sourced locally.',copy:'Support local markets and get dependable feedstock for your next cycle.',image:'hero-kcca-collection.jpeg'},{kicker:'GROW MORE CIRCULARLY',title:'Turn organic waste into value.',copy:'Order the quantity your farm needs and let us coordinate delivery.',image:'hero-third-collection.jpeg'}];return `<article class="farmer-promo" aria-label="ECO MARKET CONNECT adverts">${ads.map((ad,i)=>`<section class="farmer-promo-slide ${i===0?'active':''}" data-promo-slide="${i}" aria-hidden="${i!==0}"><div class="farmer-promo-copy"><span class="promo-kicker">${ad.kicker}</span><h2>${ad.title}</h2><p>${ad.copy}</p><button ${forGenerator?'data-action="submit-waste"':'data-go="cart"'}>${forGenerator?'Submit waste':'Order now'} ${icon('arrow_forward')}</button></div><div class="farmer-promo-art" role="img" aria-label="Organic waste collection" style="--promo-image:url('${ad.image}')"></div></section>`).join('')}<div class="farmer-promo-dots" aria-label="Advert slides">${ads.map((ad,i)=>`<button type="button" class="${i===0?'active':''}" data-promo-index="${i}" aria-label="Show advert ${i+1}" aria-current="${i===0?'true':'false'}"></button>`).join('')}</div></article>`}
function startPromoCarousel(){clearInterval(promoTimer);const roots=[...document.querySelectorAll('.farmer-promo')];if(!roots.length)return;const advance=(root,step)=>{const slides=[...root.querySelectorAll('[data-promo-slide]')],dots=[...root.querySelectorAll('[data-promo-index]')];if(!slides.length)return;let i=slides.findIndex(x=>x.classList.contains('active'));i=(i+step+slides.length)%slides.length;slides.forEach((x,n)=>{x.classList.toggle('active',n===i);x.setAttribute('aria-hidden',n===i?'false':'true')});dots.forEach((x,n)=>{x.classList.toggle('active',n===i);x.setAttribute('aria-current',n===i?'true':'false')})};roots.forEach(root=>{root.addEventListener('touchstart',e=>{promoTouchX=e.changedTouches[0].clientX},{passive:true});root.addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-promoTouchX;if(Math.abs(dx)>40)advance(root,dx<0?1:-1)},{passive:true})});promoTimer=setInterval(()=>roots.forEach(root=>advance(root,1)),4500)}
function home(){
 const total=db.inventory.reduce((sum,w)=>sum+w.stock,0),recent=db.orders[0],now=new Date(),day=now.getDate(),ordinal=day%10===1&&day!==11?'st':day%10===2&&day!==12?'nd':day%10===3&&day!==13?'rd':'th';
 const date=now.toLocaleDateString('en-UG',{weekday:'long',month:'long'})+` ${day}${ordinal}, ${now.getFullYear()}`;
 const tips=['Keep feedstock dry and well covered to preserve quality.','Environmental conservation  for today and tomorrow.','Turn your substrate regularly for even aeration and healthy larvae.','Separate contaminated material before processing your collection.'];
 const advice=tips[now.getDate()%tips.length];
 const trackButton=`<button class="btn btn-outline" data-go="tracking">${icon('local_shipping')} ${recent?'Track recent order':'Track a recent order'}</button>`;
 const actions=`<div class="farmer-home-actions"><button class="btn btn-primary" data-go="cart">${icon('shopping_cart')} Order now</button>${trackButton}</div>`;
 const branches=[['Kampala','Nakasero Market · Kalerwe Market'],['Mukono','Mukono Collection Hub'],['Jinja','Jinja Collection Hub'],['Luwero','Central Region collection point'],['Ntungamo','Western Region collection point']];
 const branchesSection=`<section class="home-branches"><div class="home-branches-heading"><div><span class="eyebrow">LOCAL COLLECTION NETWORK</span><h2>Our branches near you</h2><p>Collection points serving farmers across Uganda.</p></div></div><div class="home-branch-grid">${branches.map(([place,detail])=>`<article class="home-branch-card"><span class="home-branch-icon">${icon('location_on')}</span><div><strong>${place}</strong><small>${detail}</small></div></article>`).join('')}</div></section>`;
 const stockCard=`<section class="card pad farmer-stock-summary"><span class="eyebrow">Available Organic Waste</span><div class="farmer-stock-number">${total.toLocaleString()} <small>kg</small></div><p>Ready to order for your farm</p></section>`;
 const tipCard=`<section class="card pad farmer-advice"><div class="list-icon">${icon('agriculture')}</div><div><span class="eyebrow">FARM TIP FOR TODAY</span><p>${advice}</p><small>${greeting()} · ${date}</small></div></section>`;
 return `<div class="page farmer-home-page"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Edit profile photo">${userAvatar()}</button><div class="farmer-greeting-copy"><span>${greeting()}, ${esc(db.user.name.split(' ')[0])}</span><strong>${date}</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${notificationBell()}</button></div></section><section class="farmer-mobile-content home-dashboard-content">${farmerPromo()}${stockCard}${tipCard}${actions}${branchesSection}</section><div class="home-desktop home-dashboard-content">${farmerPromo()}<div class="home-overview-grid">${stockCard}${tipCard}</div>${actions}${branchesSection}</div></div>`
}
function generatorHome(){const mine=db.submissions.filter(s=>s.generator===db.user.name),total=mine.reduce((sum,s)=>sum+s.qty,0);return `<div class="page farmer-home-page generator-page"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Open profile">${userAvatar()}</button><div class="farmer-greeting-copy"><span>Welcome, ${esc(db.user.name.split(" ")[0])}</span><strong>${icon("location_on")} ${esc(db.user.location||"Your collection area")}</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon("notifications")}<i></i></button></div></section><div class="generator-page-content">${farmerPromo(true)}<section class="card pad generator-total"><span class="eyebrow">TOTAL WASTE SUBMITTED</span><div class="generator-total-value">${total.toLocaleString()} <small>kg</small></div><p>Across ${mine.length} submission${mine.length===1?"":"s"}</p></section><section class="card pad generator-submit-cta"><div><span class="eyebrow">HAVE WASTE TO SUBMIT?</span><h2>Ready for collection?</h2><p>Add the amount and a contact number. Staff will arrange pickup.</p></div><button class="btn btn-primary" data-action="submit-waste">${icon("add")} Submit waste</button></section><section class="card pad"><div class="section-head"><h2>Your submissions</h2><span class="badge">${mine.length}</span></div>${mine.length?`<div class="list">${mine.map(s=>`<div class="list-row"><div class="list-icon">${icon("recycling")}</div><div class="row-main"><strong>${s.qty.toLocaleString()} kg · Unsorted organic waste</strong><small>${esc(s.phone)} · ${esc(s.date)}</small></div><span class="badge ${s.status==="Submitted"?"orange":s.status==="Collected"?"":"blue"}">${esc(s.status)}</span></div>`).join("")}</div>`:`<div class="empty"><p>Your submissions and pickup updates will appear here.</p></div>`}</section></div></div>`}
function generatorSubmissions(){const mine=db.submissions.filter(s=>s.generator===db.user.name),steps=['Submitted','Confirmed','On the way','Collected'];const progress=s=>Math.max(0,steps.indexOf(s.status));return `<div class="page farmer-home-page generator-page"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Open profile">${userAvatar()}</button><div class="farmer-greeting-copy"><span>Submit waste</span><strong>${icon("location_on")} ${esc(db.user.location||"Your collection area")}</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon("notifications")}<i></i></button></div></section><div class="generator-page-content"><section class="generator-form-intro"><span class="eyebrow">WASTE PICKUP REQUEST</span><h1>Submit waste for collection</h1><p>Share the waste details and our staff will confirm when pickup is arranged.</p></section><section class="card pad generator-form-card"><form id="generator-submit-form" class="form-grid"><label class="field">Amount available (kg)<input name="qty" type="number" min="1" step="any" required placeholder="e.g. 250"></label><label class="field">Preferred pickup date<input name="pickupDate" type="date" min="${new Date().toISOString().slice(0,10)}" required></label><label class="field full">Generator / contact person<input name="contact" value="${esc(db.user.name)}" required placeholder="Name of the person handing over waste"></label><label class="field">Generator phone number<input name="phone" type="tel" value="${esc(db.user.phone||"")}" required placeholder="+256 700 000 000"></label><label class="field">Alternate telephone number<input name="alternatePhone" type="tel" placeholder="Optional backup number"></label><label class="field full">Pickup location / landmark<textarea name="location" required placeholder="Market, area, street, and nearby landmark">${esc(db.user.location||"")}</textarea></label><label class="field">Preferred pickup time<select name="pickupTime"><option>Any time</option><option>Morning (8am–12pm)</option><option>Afternoon (12pm–5pm)</option></select></label><label class="field">Waste condition<select name="condition"><option>Ready for collection</option><option>Needs bags or containers</option><option>Staff assistance needed</option></select></label><label class="field full">Additional notes<textarea name="notes" placeholder="Access instructions, waste handling details, or other notes"></textarea></label><div class="field full"><button class="btn btn-primary btn-block">${icon("send")} Submit pickup request</button></div></form></section><section class="generator-tracking-section"><div class="section-head"><div><h2>Track your waste</h2><small class="muted">Follow staff confirmation and pickup progress</small></div><span class="badge">${mine.length} requests</span></div>${mine.length?mine.map(s=>{const n=progress(s);return `<article class="card pad generator-tracking-card"><div class="section-head"><div><span class="eyebrow">${esc(s.id)}</span><h3>${s.qty.toLocaleString()} kg · Unsorted organic waste</h3></div><span class="badge ${s.status==='Submitted'?'orange':s.status==='Collected'?'':'blue'}">${esc(s.status)}</span></div><p class="muted generator-track-detail">${esc(s.location)} · ${esc(s.phone)}<br>Pickup: ${esc(s.pickupDate||'Date to be arranged')} · ${esc(s.pickupTime||'Any time')}</p><div class="generator-trackline">${steps.map((step,i)=>`<div class="generator-track-step ${i<=n?'done':''}"><span>${i<n?icon('check'):i+1}</span><small>${step}</small></div>`).join('')}</div>${s.status==='Cancelled'?'<p class="generator-track-note">This pickup request was cancelled. Contact staff if you still need collection.</p>':''}${s.status==='Collected'&&s.stockAdded?'<p class="generator-track-note collected">Collected and added to available stock.</p>':''}</article>`}).join(''):`<div class="card empty"><p>Your pickup requests and staff updates will appear here after you submit waste.</p></div>`}</section></div></div>`}
function generatorTracking(){const mine=db.submissions.filter(s=>s.generator===db.user.name),steps=['Submitted','Confirmed','On the way','Collected','Verified'];return `<div class="page farmer-home-page generator-page"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Open profile">${userAvatar()}</button><div class="farmer-greeting-copy"><span>Track waste</span><strong>${icon("location_on")} ${esc(db.user.location||"Your collection area")}</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon("notifications")}<i></i></button></div></section><div class="generator-page-content"><section class="generator-form-intro"><span class="eyebrow">PICKUP UPDATES</span><h1>Track your waste</h1><p>See when staff confirm your request, collect the waste, and verify it for stock.</p></section><div class="section-head"><h2>Your pickup requests</h2><span class="badge">${mine.length} requests</span></div>${mine.length?mine.map(s=>{const upto=steps.indexOf(s.status);return `<article class="card pad generator-tracking-card"><div class="section-head"><div><span class="eyebrow">${esc(s.id)}</span><h3>${s.qty.toLocaleString()} kg · Unsorted organic waste</h3></div><span class="badge ${s.status==='Submitted'?'orange':s.status==='Verified'?'':'blue'}">${esc(s.status)}</span></div><p class="muted generator-track-detail">Contact: ${esc(s.contact||s.generator)} · ${esc(s.phone)}${s.alternatePhone?` · Backup ${esc(s.alternatePhone)}`:''}<br>Pickup point: ${esc(s.location)}<br>Requested: ${esc(s.pickupDate||'Date to be arranged')} · ${esc(s.pickupTime||'Any time')}</p><div class="generator-trackline">${steps.map((step,i)=>`<div class="generator-track-step ${upto>=i?'done':''}"><span>${upto>i?icon('check'):i+1}</span><small>${step}</small></div>`).join('')}</div>${s.status==='Cancelled'?'<p class="generator-track-note">Staff cancelled this request. Contact the team for details.</p>':''}${s.status==='Verified'?'<p class="generator-track-note collected">Staff verified the collected waste and added it to available stock.</p>':''}${s.notes?`<small class="muted">Note: ${esc(s.notes)}</small>`:''}</article>`}).join(''):`<div class="card empty"><p>No waste requests yet. Submit waste and staff pickup updates will appear here.</p><button class="btn btn-primary" data-go="submissions">Submit waste</button></div>`}</div></div>`}
function submitWasteModal(){return openModal("Submit waste for collection",`<p class="muted">Tell staff how much organic waste is ready and the best number to reach you.</p><form id="generator-submit-form" class="form-grid"><label class="field full">Amount available (kg)<input name="qty" type="number" min="1" step="any" required placeholder="e.g. 250"></label><label class="field full">Contact name<input name="contact" value="${esc(db.user.name)}" required></label><label class="field full">Telephone number<input name="phone" type="tel" value="${esc(db.user.phone||"")}" required placeholder="+256 700 000 000"></label><label class="field full">Collection location<input name="location" value="${esc(db.user.location||"")}" required placeholder="Market, area, or landmark"></label><div class="field full"><button class="btn btn-primary btn-block">Notify staff and submit</button></div></form>`)}
function categoryPage(){return cartPage()}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening'}
function favoritesPage(){const items=db.inventory.filter(w=>db.favorites.includes(w.id));return `<div class="page farmer-home-page favorites-mobile"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Edit profile photo">${userAvatar()}</button><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${notificationBell()}</button></div></section><section class="farmer-mobile-content favorites-content"><div class="explore-heading"><div><span class="promo-kicker">YOUR SAVED SUPPLIES</span><h1>Favorites</h1><p>Keep your go-to feedstock close at hand.</p></div></div>${items.length?`<div class="category-product-grid">${items.map(categoryProductCard).join('')}</div>`:`<div class="orders-empty favorites-empty"><div class="orders-empty-icon">${icon('favorite')}</div><h2>No favorites yet</h2><p>Save supplies with the heart button and they’ll be collected here.</p><button class="btn btn-primary" data-go="market">Explore supplies ${icon('arrow_forward')}</button></div>`}</section></div>`}
function orderHistoryPanel(){const orders=db.orders;return `<section class="cart-order-history"><div class="section-head"><div><h2>Recent orders</h2><small>Quantity and delivery recipient</small></div><span class="badge">${orders.length} total</span></div>${orders.length?`<div class="cart-order-list">${orders.map(o=>{const kg=o.items.reduce((sum,item)=>sum+(item.unit==='kg'?item.qty:item.qty*50),0);return `<article class="recent-order-summary"><div class="recent-order-quantity"><strong>${kg.toLocaleString()} kg</strong><small>ordered</small></div><div class="recent-order-detail"><small>Delivery address</small><strong>${esc(o.address||'Not provided')}</strong></div><div class="recent-order-detail"><small>Received by</small><strong>${esc(o.receiverName||'Not provided')}</strong><span>${esc(o.receiverPhone||'Contact not provided')}</span></div><div class="recent-order-status"><span class="badge ${o.status==='Delivered'?'':'orange'}">${esc(o.status)}</span></div></article>`}).join('')}</div>`:`<div class="orders-empty cart-history-empty"><div class="orders-empty-icon">${icon('local_shipping')}</div><h2>No orders yet</h2><p>Your orders will appear here after checkout.</p></div>`}</section>`}
function productDetail(id){
 const w=db.inventory.find(x=>x.id===id);
 if(!w)return `<div class="page"><button class="btn btn-outline" data-go="market">${icon('arrow_back')} Back to Explore</button><section class="card empty" style="margin-top:20px"><h2>Supply not found</h2><p>This listing may no longer be available.</p></section></div>`;
 const categoryText='Sorted organic waste, quality checked and ready for BSF farms.';
 const related=db.inventory.filter(x=>x.id!==w.id).slice(0,4);
 return `<div class="page farmer-home-page product-mobile"><section class="farmer-mobile-head product-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Edit profile photo">${userAvatar()}</button><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${notificationBell()}</button></div></section><section class="product-mobile-content"><div class="product-mobile-photo" style="background-image:url('${imageFor(w.color)}')"><button class="product-back-icon" data-go="market" aria-label="Back to Explore">${icon('arrow_back')}</button><span class="product-quality-tag">${icon('verified')} Quality checked</span><button class="product-favorite ${db.favorites.includes(w.id)?'saved':''}" data-favorite="${w.id}" aria-label="Toggle favorite">${icon('favorite')}</button></div><div class="product-mobile-info"><div class="product-mobile-category"><span>Sorted organic waste</span><span class="product-stock-label"><i></i> Available now</span></div><h1>${esc(w.name)}</h1><div class="product-location">${icon('location_on')} ${esc(w.location)}</div><p class="product-description">${categoryText}</p><section class="product-source-card"><div class="product-source-icon">${icon('recycling')}</div><div><strong>Collected ${esc(w.fresh.replace(/^Collected /i,''))}</strong><small>Sorted by our local collection team</small></div><span class="product-source-check">${icon('verified')}</span></section><div class="product-detail-facts"><div><span>Available quantity</span><strong>${w.stock.toLocaleString()} kg</strong></div><div><span>Order unit</span><strong>${esc(w.unit)}</strong></div><div><span>Collection point</span><strong>${esc(w.location.split(',')[0])}</strong></div></div><div class="product-buy-row"><div class="product-detail-price"><strong>${money(w.price)}</strong><span>/ sack</span></div><div class="product-quantity-control"><button data-product-qty="dec" aria-label="Decrease quantity">−</button><input id="product-qty" type="number" min="1" value="1" aria-label="Quantity in sacks"><button data-product-qty="inc" aria-label="Increase quantity">+</button></div></div><button class="btn btn-primary btn-block product-add" data-add="${w.id}" data-add-qty="1">${icon('shopping_bag')} Add to order</button><div class="product-delivery-note">Delivery to Wakiso is arranged after our team confirms your order.</div>${related.length?`<section class="product-related"><div class="mobile-section-title"><h2>More sorted organic waste</h2><button class="text-link" data-go="market">See all</button></div><div class="mobile-waste-rail">${related.map(mobileWasteCard).join('')}</div></section>`:''}</div></section></div><div class="page product-detail-page product-desktop"><button class="btn btn-outline product-back" data-go="market">${icon('arrow_back')} Back to Explore</button><div class="product-detail-grid"><div class="product-detail-photo" style="background-image:url('${imageFor(w.color)}')"><span class="tag">${icon('verified')} Quality checked</span><button class="product-favorite ${db.favorites.includes(w.id)?'saved':''}" data-favorite="${w.id}" aria-label="Toggle favorite">${icon('favorite')}</button></div><section class="product-detail-info"><div class="eyebrow">Sorted organic waste</div><h1>${esc(w.name)}</h1><div class="product-location">${icon('location_on')} ${esc(w.location)}</div><p class="product-description">${categoryText} Each sack is listed at ${money(w.price)} and sourced through ECO MARKET CONNECT’s collection network.</p><div class="product-detail-facts"><div><span>Available stock</span><strong>${w.stock.toLocaleString()} kg</strong></div><div><span>Collection status</span><strong>${esc(w.fresh)}</strong></div><div><span>Order unit</span><strong>${esc(w.unit)}</strong></div></div><div class="product-detail-price"><strong>${money(w.price)}</strong><span>/ ${esc(w.unit)}</span></div><button class="btn btn-primary btn-block product-add" data-add="${w.id}">${icon('shopping_bag')} Add to order</button><small class="product-delivery-note">Delivery to Wakiso is arranged after the team confirms your order.</small></section></div></div>`
}
function marketplace(){const w=db.inventory[0],items=w?[w]:[];return `<div class="page farmer-home-page"><div class="page-heading"><div><div class="eyebrow">Organic waste</div><h1>Sorted stock</h1><p>All available stock is sorted organic waste, ready for your farm.</p></div><button class="btn btn-primary" data-go="cart">${icon('shopping_bag')} Place an order</button></div><div class="grid waste-grid">${items.map(wasteCard).join('')}</div></div>`}
function cartPage(){const address=db.user?.location||'',available=db.inventory.reduce((sum,w)=>sum+w.stock,0);return `<div class="order-page-shell"><section class="farmer-mobile-head order-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Edit profile photo">${userAvatar()}</button><div class="farmer-greeting-copy"><span>${db.user?.name==='Guest'?'Welcome':`Hi, ${esc(db.user?.name?.split(' ')[0]||'farmer')}`}</span><strong>${icon('location_on')} ${esc(db.user?.location||'Set your delivery address')}</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${notificationBell()}</button></div><div class="order-mobile-title"></div></section><div class="page order-page"><div class="page-heading"><div><div class="eyebrow">Fresh organic supplies</div><h1>Build your order</h1><p>Choose how many kilograms you need, up to the total available stock.</p></div><span class="badge">${icon('verified')} Stock updated</span></div><form id="order-form"><div class="two-col order-form-layout"><section class="card pad order-items-card"><div class="section-head"><div><h2>Available supplies</h2><small class="muted">Organic waste ready to order</small></div></div><div class="order-rate-note"><span>Price per kilogram</span><strong>UGX 250 / kg</strong><small>Your supply estimate updates as you enter a quantity.</small></div><div class="order-single-stock"><div class="order-single-stock-icon">${icon('recycling')}</div><div class="order-single-stock-copy"><strong>Available organic waste</strong><span class="order-stock-amount">${available.toLocaleString()} <small>kg</small></span><small>Organic waste ready to order</small></div><label class="field order-kg-field"><span>How much do you need?</span><div class="order-quantity-control"><input type="number" name="qty-total" min="0" max="${available}" step="any" value="0" inputmode="decimal" data-order-qty="total" data-stock="${available}" aria-label="Organic waste quantity to order"><select name="qty-unit" aria-label="Order quantity unit" data-order-unit><option value="kg">kg</option><option value="ton">tons</option></select></div></label></div><p class="order-stock-hint">Your request will be matched against the available organic waste stock.</p></section><aside class="card pad order-delivery-card"><div class="section-head"><div><div class="eyebrow">Delivery details</div><h2>Recipient & address</h2></div><span class="list-icon">${icon('local_shipping')}</span></div><div class="form-grid order-contact-fields"><label class="field full">Contact person<input name="receiverName" value="${esc(db.user?.name==='Guest'?'':db.user?.name||'')}" autocomplete="name" required placeholder="Name of person receiving delivery"></label><label class="field full">Contact number<input name="receiverPhone" value="${esc(db.user?.phone||'')}" autocomplete="tel" inputmode="tel" required placeholder="+256 700 000 000"></label><label class="field full">Delivery address<textarea name="deliveryAddress" autocomplete="street-address" required placeholder="District, town, village, and nearby landmark">${esc(address)}</textarea></label><label class="field full">Requested delivery date<input type="date" name="deliveryDate" min="${new Date().toISOString().slice(0,10)}" required></label></div><div class="order-total-box"><div class="summary-line"><span>Supplies estimate</span><strong id="order-subtotal">UGX 0</strong></div><div class="summary-line"><span>Delivery</span><strong>UGX 15,000</strong></div><div class="summary-line total"><span>Estimated total</span><strong id="order-estimate">UGX 0</strong></div></div><button class="btn btn-primary btn-block order-submit-button" type="submit">Place my order ${icon('arrow_forward')}</button><p class="muted tiny order-confirm-note">Our team will confirm availability and delivery timing.</p></aside></div></form></div></div>`}
function allocateOrderQuantity(quantity){let remaining=quantity,items=[];for(const w of db.inventory){const qty=Math.min(remaining,w.stock);if(qty>0)items.push({id:w.id,name:w.name,qty,unit:'kg',emoji:w.emoji,pricePerKg:250,price:Math.round(250*qty)});remaining-=qty;if(remaining<=0)break}return remaining?null:items}
function collectOrderForm(form){const data=new FormData(form),entered=Number(data.get('qty-total'))||0,unit=data.get('qty-unit')||'kg',quantity=unit==='ton'?entered*1000:entered,input=form.querySelector('[data-order-qty="total"]'),available=db.inventory.reduce((sum,w)=>sum+w.stock,0);if(quantity<1){input?.setCustomValidity('Enter a quantity greater than zero to place an order.');input?.reportValidity();return null}if(quantity>available){input?.setCustomValidity(`Only ${(unit==='ton'?available/1000:available).toLocaleString()} ${unit==='ton'?'tons':'kg'} is available.`);input?.reportValidity();return null}input?.setCustomValidity('');const items=allocateOrderQuantity(quantity);if(!items){toast('The available stock changed. Please review your quantity.');return null}return {items,receiverName:String(data.get('receiverName')||'').trim(),receiverPhone:String(data.get('receiverPhone')||'').trim(),address:String(data.get('deliveryAddress')||'').trim(),deliveryDate:String(data.get('deliveryDate')||'')}}
function completeOrder(details){if(!details||db.role!=='farmer'){pendingOrder=details;loginPrompt();return}for(const item of details.items){const stock=db.inventory.find(w=>w.id===item.id);if(!stock||item.qty>stock.stock){toast(`${item.name} no longer has that much stock. Please update your quantity.`);go('cart');return}}const supplies=details.items.reduce((sum,item)=>sum+item.price,0),total=supplies+15000;const order={id:'GD-'+String(Date.now()).slice(-6),date:new Date().toLocaleDateString('en-UG',{day:'numeric',month:'short',year:'numeric'}),items:details.items,total,status:'Order received',address:details.address,deliveryDate:details.deliveryDate,receiverName:details.receiverName,receiverPhone:details.receiverPhone,progress:0,stockDeducted:false};db.orders.unshift(order);pendingOrder=null;save();render();orderConfirmationModal(order);notifyUser('Order placed successfully',`Order ${order.id} was placed successfully.`)}
function placeOrder(details){completeOrder(details)}
function confirmation(){let o=db.orders[0];return `<div class="page"><section class="card pad" style="max-width:760px;margin:35px auto;text-align:center;padding:45px 32px"><div style="width:76px;height:76px;border-radius:50%;margin:0 auto 20px;background:#e9f5eb;color:var(--green);display:grid;place-items:center;font-size:36px">${icon('check_circle')}</div><div class="eyebrow">Order placed</div><h1 style="margin-top:9px">Your farm’s next delivery is in motion.</h1><p class="muted" style="max-width:500px;margin:10px auto 22px">Requested delivery date: <strong>${esc(o?.deliveryDate||'Not specified')}</strong><br>We’ve sent your order to the ECO MARKET CONNECT team. We’ll call to confirm availability and your delivery window.</p><div class="order-banner" style="max-width:490px;margin:0 auto 24px;text-align:left"><span><small class="muted">ORDER REFERENCE</small><br><strong>${o?.id}</strong></span><span class="badge orange">${o?.status}</span></div><div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap"><button class="btn btn-primary" data-go="tracking">Track this order ${icon('arrow_forward')}</button><button class="btn btn-outline" data-go="market">Continue shopping</button></div></section></div>`}
function orderConfirmationModal(o){const modal=openModal('Order placed successfully',`<div class="order-success-modal"><div class="order-success-icon">${icon('check_circle')}</div><p class="muted">Your order has been sent to the ECO MARKET CONNECT team.</p><div class="order-success-reference"><span>ORDER REFERENCE</span><strong>${esc(o.id)}</strong></div><div class="order-success-details"><div><span>Requested delivery</span><strong>${esc(o.deliveryDate||'Not specified')}</strong></div><div><span>Order total</span><strong>${money(o.total)}</strong></div></div><p class="muted tiny">We’ll call to confirm availability and your delivery window.</p><button class="btn btn-primary btn-block" data-go="tracking" data-modal-close>Track this order ${icon('arrow_forward')}</button><button class="btn btn-outline btn-block" style="margin-top:9px" data-modal-close>Continue</button></div>`);modal.querySelector('[data-go="tracking"]').addEventListener('click',()=>{modal.remove();go(`tracking/${encodeURIComponent(o.id)}`)})}
function orderMini(o){return `<div class="order-banner"><span><small class="muted">${o.id} · ${o.date}</small><br><strong>${money(o.total)}</strong><br><small>Delivery requested: ${esc(o.deliveryDate||'Not specified')}</small></span><span class="badge orange">${o.status}</span></div><div class="list">${o.items.map(x=>`<div class="list-row"><div class="table-emoji">${x.emoji}</div><div class="row-main"><strong>${esc(x.name)}</strong><small>${x.unit==='kg'?`${x.qty.toLocaleString()} kg`:`${x.qty} × 50 kg sacks`}</small></div><strong>${money(x.unit==='kg'?x.price:x.price*x.qty)}</strong></div>`).join('')}</div><button class="btn btn-soft btn-block" style="margin-top:15px" data-go="tracking">View order progress ${icon('arrow_forward')}</button>`}
function tracking(){
 const route=location.hash.replace(/^#\/?/,'');const match=route.match(/^tracking\/(.+)$/);const focusedId=match?decodeURIComponent(match[1]):null;const orders=focusedId?db.orders.filter(o=>o.id===focusedId):db.orders;
 const inFilter=o=>focusedId||orderFilter==='All'||(orderFilter==='Received'&&o.status==='Order received')||(orderFilter==='Pending'&&!['Order received','Delivered','Cancelled'].includes(o.status))||(orderFilter==='Cancelled'&&o.status==='Cancelled');
 const countFor=x=>x==='All'?orders.length:x==='Received'?orders.filter(o=>o.status==='Order received').length:x==='Pending'?orders.filter(o=>!['Order received','Delivered','Cancelled'].includes(o.status)).length:orders.filter(o=>o.status==='Cancelled').length;
 const visible=orders.filter(inFilter);
 const mobileOrders=visible.map(o=>{
  const progress=Math.max(0,o.progress||0),steps=['Received','Confirmed','Preparing','On the way','Delivered'],current=steps[Math.min(progress,4)];
  return `<article class="mobile-order-card"><div class="mobile-order-top"><div><span class="promo-kicker">${esc(o.id)}</span><small>Placed ${esc(o.date)}</small></div><span class="badge ${progress>=3?'':'orange'}">${esc(o.status)}</span></div><h2>${o.items.map(i=>esc(i.name)).join(', ')}</h2><div class="mobile-order-meta"><span>${(()=>{const qty=o.items.reduce((a,i)=>a+i.qty,0);return o.items.every(i=>i.unit==='kg')?`${qty.toLocaleString()} kg`:`${qty} sack${qty===1?'':'s'}`})()}</span><i></i><strong>${money(o.total)}</strong></div><div class="order-progress-track">${steps.map((step,i)=>`<span class="${i<=progress?'done':''} ${i===progress?'current':''}"></span>`).join('')}</div><div class="order-stage-labels">${steps.map((step,i)=>`<span class="${i===progress?'current':''}">${step==='Confirmed'?'Confirm':step==='Preparing'?'Prepare':step==='On the way'?'On way':step}</span>`).join('')}</div><div class="order-current-step">${icon(progress>=4?'check_circle':'local_shipping')}<span><small>Current status</small><strong>${esc(current)}</strong></span></div><div class="mobile-order-next">${icon('schedule')}<span><small>Next update</small><strong>${progress>=4?'Delivered to your farm.':progress===3?'Your delivery is on the way to your farm.':progress===2?'Your order is being prepared for dispatch.':progress===1?'Our team is arranging your delivery window.':o.status==='Cancelled'?'This order was cancelled. Contact us if you need help.':'Our team will confirm availability and delivery timing.'}</strong></span></div><div class="mobile-order-delivery">${icon('location_on')}<span>${esc(o.address)}<br><small>Requested delivery: ${esc(o.deliveryDate||'Not specified')}</small></span></div><button class="mobile-order-contact" data-action="help">${icon('call')} Contact ECO MARKET CONNECT</button></article>`
 }).join('');
 const filters=focusedId?[]:['All','Received','Pending','Cancelled'];
 const desktopOrders=orders.length?orders.map(o=>`<div class="card pad desktop-order-card" style="margin-bottom:17px"><div class="section-head"><div><div class="eyebrow">${esc(o.id)}</div><h2 style="margin:5px 0 0">${o.items.map(i=>esc(i.name)).join(', ')}</h2><span class="muted tiny">Placed ${esc(o.date)} · ${o.items.reduce((sum,i)=>sum+i.qty,0).toLocaleString()} ${o.items.every(i=>i.unit==='kg')?'kg':'sacks'} · ${money(o.total)}</span></div><span class="badge ${(o.progress||0)>=3?'':'orange'}">${esc(o.status)}</span></div><div class="trackline">${['Received','Confirmed','Preparing','On the way','Delivered'].map((step,i)=>`<div class="track-step ${i<=(o.progress||0)?'done':''}"><span class="track-dot">${i<(o.progress||0)?icon('check'):i+1}</span><span>${step}</span></div>`).join('')}</div><div class="list-row"><div class="list-icon">${icon('location_on')}</div><div class="row-main"><strong>Delivery address</strong><small>${esc(o.address)}<br>Requested delivery: ${esc(o.deliveryDate||'Not specified')}</small></div><button class="btn btn-outline" data-action="help">${icon('call')} Contact team</button></div></div>`).join(''):`<div class="card empty">${icon('local_shipping')}<h2>No deliveries to track yet</h2><p>Your orders will appear here as soon as you place one.</p><button class="btn btn-primary" data-go="market">Browse supplies</button></div>`;
 return `<div class="page farmer-home-page orders-mobile"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Edit profile photo">${userAvatar()}</button><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${notificationBell()}</button></div></section><section class="farmer-mobile-content orders-mobile-content"><div class="orders-title-row"><div><span class="promo-kicker">YOUR FARM SUPPLIES</span><h1>${focusedId?'Order tracking':'My orders'}</h1><p>${focusedId?`Tracking order ${esc(focusedId)} from confirmation to delivery.`:'Track your supplies from collection to delivery.'}</p></div>${focusedId?`<button class="btn btn-outline" data-go="tracking">All orders</button>`:`<button class="orders-shop" data-go="market">${icon('add')}<span>Shop</span></button>`}</div><div class="order-filter-tabs">${filters.map(x=>`<button class="${orderFilter===x?'active':''}" data-order-filter="${x}">${x}<small>${countFor(x)}</small></button>`).join('')}</div>${mobileOrders||`<div class="orders-empty"><div class="orders-empty-icon">${icon('local_shipping')}</div><h2>${orderFilter==='All'?'No orders yet':`No ${orderFilter.toLowerCase()} orders`}</h2><p>${orderFilter==='All'?'Your supplies and delivery updates will appear here after you place an order.':'Try another order filter, or browse available organic waste.'}</p><button class="btn btn-primary" data-go="market">Explore supplies ${icon('arrow_forward')}</button></div>`}</section></div><div class="orders-desktop"><div class="page"><div class="page-heading"><div><div class="eyebrow">Stay in the loop</div><h1>Orders & delivery</h1><p>Follow every order from confirmation to your farm gate.</p></div><button class="btn btn-primary" data-go="market">${icon('add')} Place an order</button></div>${desktopOrders}</div></div>`
}
function profile(){const u=db.user||{},name=esc(u.name||''),phone=esc(u.phone||''),email=esc(u.email||''),farm=esc(u.farm||''),location=esc(u.location||'');const farmType=u.farmType||'Black Soldier Fly (BSF)';const identity=`<div class="profile-identity-card"><div class="profile-identity-avatar profile-photo-preview">${userAvatar()}</div><div class="profile-identity-copy"><strong>${name}</strong><span>${db.role==='generator'?'Generator account':'Farmer account'}</span></div><label class="profile-photo-action">${icon('edit')} Change photo<input type="file" data-profile-photo accept="image/*" aria-label="Choose profile photo"></label></div>`;const personal=`<section class="profile-mobile-card"><div class="profile-card-heading"><span class="profile-section-icon">${icon('person')}</span><div><h2>Personal details</h2><small>Your contact information</small></div></div><label class="profile-field">Full name<input name="name" value="${name}" autocomplete="name" required></label><label class="profile-field">Phone number<input name="phone" value="${phone}" autocomplete="tel" inputmode="tel" required></label>${db.role==='generator'?'':`<label class="profile-field">Email address<input name="email" value="${email}" autocomplete="email" type="email"></label>`}</section>`;const farmDetails=`<section class="profile-mobile-card"><div class="profile-card-heading"><span class="profile-section-icon">${icon('agriculture')}</span><div><h2>${db.role==='generator'?'Collection details':'Farm & delivery'}</h2><small>Where we can reach you</small></div></div>${db.role==='generator'?'':`<label class="profile-field">Farm / business name<input name="farm" value="${farm}" autocomplete="organization"></label><label class="profile-field">Farm type<select name="farmType"><option ${farmType==='Black Soldier Fly (BSF)'?'selected':''}>Black Soldier Fly (BSF)</option><option ${farmType==='Other livestock'?'selected':''}>Other livestock</option></select></label>`}<label class="profile-field">${db.role==='generator'?'Collection location':'Delivery address'}<textarea name="location" autocomplete="street-address" required placeholder="District, town, village, and nearby landmark">${location}</textarea></label></section>`;return `<div class="page farmer-home-page profile-mobile"><section class="farmer-mobile-head profile-mobile-head"><div class="farmer-greeting-row"><button type="button" class="avatar farmer-head-avatar" data-go="profile" aria-label="Edit profile photo">${userAvatar()}</button><div class="farmer-greeting-copy"><span>Hi, ${esc(u.name?.split(' ')[0]||'farmer')}</span><strong>${icon('location_on')} ${location||'Add your delivery address'}</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${notificationBell()}</button></div></section><section class="farmer-mobile-content profile-mobile-content"><div class="profile-title-block"><span class="promo-kicker">YOUR ACCOUNT</span><h1>My profile</h1><p>Update your contact details and collection location.</p></div><form data-profile-form class="profile-mobile-form">${identity}${personal}${farmDetails}<button class="btn btn-primary btn-block profile-save-button" type="submit">${icon('save')} Save changes</button></form><button class="profile-help-link" data-action="help">${icon('support_agent')} Need help with your account? <span>${icon('arrow_forward')}</span></button><button class="profile-logout" data-action="logout">${icon('logout')} Sign out</button></section></div><div class="profile-desktop"><div class="page"><div class="page-heading"><div><div class="eyebrow">Your account</div><h1>My farm profile</h1><p>Keep your details up to date so deliveries reach you smoothly.</p></div></div><form data-profile-form><div class="two-col"><section class="card pad profile-desktop-card">${identity}<div class="form-grid"><label class="field">Full name<input name="name" value="${name}" autocomplete="name" required></label><label class="field">Phone number<input name="phone" value="${phone}" autocomplete="tel" required></label><label class="field full">Email address<input name="email" value="${email}" autocomplete="email" type="email"></label></div></section><aside class="card pad profile-desktop-card"><div class="profile-card-heading"><span class="profile-section-icon">${icon('agriculture')}</span><div><h2>Farm & delivery</h2><small>Delivery contact and location</small></div></div><label class="field">Farm / business name<input name="farm" value="${farm}" autocomplete="organization"></label><label class="field" style="margin-top:15px">Farm type<select name="farmType"><option ${farmType==='Black Soldier Fly (BSF)'?'selected':''}>Black Soldier Fly (BSF)</option><option ${farmType==='Other livestock'?'selected':''}>Other livestock</option></select></label><label class="field" style="margin-top:15px">Delivery address<textarea name="location" autocomplete="street-address" required placeholder="District, town, village, and nearby landmark">${location}</textarea></label></aside></div><button class="btn btn-primary profile-save-button" style="margin-top:18px" type="submit">${icon('save')} Save changes</button></form></div></div>`}
function staffProfile(){const u=db.user||{};return `<div class="page staff-profile-page"><div class="page-heading"><div><div class="eyebrow">STAFF ACCOUNT</div><h1>My profile</h1><p>View your staff account details and sign out.</p></div></div><section class="card pad staff-profile-card"><div class="staff-profile-identity"><div class="avatar">${userAvatar()}</div><div><h2>${esc(u.name||'Staff member')}</h2><span class="badge">${esc(u.title||'Staff account')}</span></div></div><div class="staff-profile-details"><div><small>Full name</small><strong>${esc(u.name||'Not provided')}</strong></div><div><small>Role</small><strong>${esc(u.title||'Staff')}</strong></div><div><small>Phone number</small><strong>${esc(u.phone||'Not provided')}</strong></div><div><small>Email address</small><strong>${esc(u.email||'Not provided')}</strong></div><div><small>Work location</small><strong>${esc(u.location||'Not provided')}</strong></div></div><button class="btn btn-outline btn-block staff-signout" data-action="logout">${icon('logout')} Sign out</button></section></div>`}
function staffHome(){const low=db.inventory.filter(w=>w.stock<250).length,pending=db.submissions.filter(s=>s.status==='Submitted');return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Operations overview</div><h1>Good morning, Amina </h1><p>Here’s what’s moving across the ECO MARKET CONNECT network today.</p></div><button class="btn btn-primary" data-go="collection">${icon('add')} Log a collection</button></div><div class="grid stats-grid">${stat('Available stock',db.inventory.reduce((s,w)=>s+w.stock,0).toLocaleString()+' kg','inventory_2','Sorted organic waste')}${stat('Open orders',db.orders.filter(o=>o.progress<4).length+18,'receipt_long','↑ 6 new this week')}${stat('Generator pickups',pending.length,'recycling','Awaiting staff confirmation')}${stat('Needs attention',low+' low stock','warning','Review stock levels')}</div>${pending.length?`<section class="card pad"><div class="section-head"><h2> New generator submissions</h2><span class="badge orange">${pending.length} awaiting review</span></div><div class="list">${pending.map(s=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${esc(s.generator)} · ${s.qty.toLocaleString()} kg of unsorted organic waste</strong><small>${esc(s.location)} · ${esc(s.phone)} · ${esc(s.date)}</small></div><button class="btn btn-primary" data-generator-review="${s.id}">Review & confirm</button></div>`).join('')}</div></section>`:''}<div class="grid dashboard-cols"><section class="card pad"><div class="section-head"><h2>Latest farmer orders</h2><button class="text-link" data-go="stafforders">Manage orders ${icon('arrow_forward')}</button></div>${db.orders.length?`<div class="list">${db.orders.slice(0,4).map(o=>`<div class="list-row"><div class="list-icon">${icon('receipt_long')}</div><div class="row-main"><strong>${o.id} · ${o.items.map(i=>i.name).join(', ')}</strong><small>${o.address} · ${o.date}</small></div><strong>${money(o.total)}</strong><span class="badge orange">${o.status}</span><button class="icon-btn" data-order-status="${o.id}">${icon('more_horiz')}</button></div>`).join('')}</div>`:`<div class="list"><div class="list-row"><strong>No farmer orders yet</strong></div></div>`}</section><section class="card pad"><div class="section-head"><h2>Recent collections</h2><button class="text-link" data-go="collection">View all</button></div><div class="list">${db.collections.slice(0,4).map(c=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${esc(c.type)} · ${c.qty} kg</strong><small>${esc(c.agent)} · ${esc(c.place)}</small></div><span class="badge">${esc(c.status)}</span></div>`).join('')}</div><div class="section-head" style="margin-top:22px"><h2>Stock watch</h2><button class="text-link" data-go="inventory">Inventory</button></div>${db.inventory.filter(w=>w.stock<500).slice(0,3).map(w=>`<div class="list-row"><div class="table-emoji">${w.emoji}</div><div class="row-main"><strong>${w.name}</strong><small>${w.stock} kg remaining</small></div></div>`).join('')}</section></div></div>`}
function inventoryPage(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Supply management</div><h1>Organic waste stock</h1><p>All listed stock is sorted organic waste, ready for farmer orders.</p></div><button class="btn btn-primary" data-action="new-listing">${icon('add')} Add stock</button></div><div class="toolbar"><label class="searchbar">${icon('search')}<input id="inventory-search" placeholder="Search stock"></label><div class="toolbar-group"><select class="select" id="stock-filter"><option>All stock levels</option><option>Low stock</option><option>In stock</option></select><button class="btn btn-outline" data-action="export">${icon('download')} Export</button></div></div><section class="card table-wrap"><table class="table"><thead><tr><th>Stock entry</th><th>Condition</th><th>Price / sack</th><th>Available</th><th>Source / area</th><th>Status</th><th></th></tr></thead><tbody id="inventory-body">${inventoryRows(db.inventory)}</tbody></table></section><div class="grid stats-grid" style="margin-top:18px">${stat('Stock entries',db.inventory.length,'inventory_2','Sorted organic waste')}${stat('Total available',db.inventory.reduce((s,w)=>s+w.stock,0).toLocaleString()+' kg','scale','Ready for allocation')}${stat('Low stock items',db.inventory.filter(w=>w.stock<250).length,'warning','Below 250 kg threshold')}${stat('Collections logged',db.collections.length,'recycling','This prototype session')}</div></div>`}
function inventoryRows(items){return items.map(w=>`<tr><td><div class="table-item"><span class="table-emoji">${w.emoji||'♻️'}</span>${esc(w.name||'Sorted organic waste')}</div></td><td>Sorted organic waste</td><td>${money(w.price)}</td><td><strong>${w.stock.toLocaleString()} kg</strong></td><td>${esc(w.location)}</td><td><span class="badge ${w.stock<250?'orange':''}">${w.stock<250?'Low stock':'Available'}</span></td><td><button class="icon-btn" data-edit="${w.id}">${icon('edit')}</button></td></tr>`).join('')}
function collectionPage(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Field operations</div><h1>Log a collection</h1><p>Record organic waste. Approved collections enter stock as sorted organic waste.</p></div><span class="badge">${icon('wifi')} Sync ready</span></div><div class="two-col"><section class="card pad"><div class="section-head"><h2>Collection details</h2><span class="badge">New field log</span></div><form id="collection-form"><div class="form-grid"><label class="field">Collected quantity (kg)<input type="number" name="qty" min="1" placeholder="e.g. 250" required></label><label class="field">Field agent<select name="agent"><option>Sarah Namusoke</option><option>Peter Okello</option><option>Grace Akello</option><option>Myself</option></select></label><label class="field">Collection point<input name="place" placeholder="Market, farm, or collection hub" required></label><label class="field">Collection date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label class="field">Sorting check<select name="quality"><option>Passed — add as sorted stock</option><option>Needs review</option><option>Rejected</option></select></label><label class="field full">Field notes<textarea name="notes" placeholder="Condition, moisture, contamination or other observations"></textarea></label><div class="field full"><button class="btn btn-primary btn-block">${icon('save')} Save collection & update stock</button></div></div></form></section><section><div class="card pad"><div class="section-head"><h2>Today’s field activity</h2><span class="badge">${db.collections.length} logs</span></div><div class="list">${db.collections.map(c=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${esc(c.type)} · ${c.qty} kg</strong><small>${esc(c.agent)} · ${esc(c.place)}<br>${esc(c.date)}</small></div><span class="badge ${c.status==='Awaiting review'?'orange':''}">${esc(c.status)}</span></div>`).join('')}</div></div><div class="notice green" style="margin-top:15px">${icon('offline_bolt')} <span>Field logs are saved on this device for your demo. A connected deployment can sync them across the team.</span></div></section></div></div>`}
function staffOrders(){const pending=db.submissions.filter(s=>!['Collected','Verified','Cancelled'].includes(s.status));return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Farmer demand & generator pickups</div><h1>Orders management</h1><p>Review farmer requests and coordinate generator waste pickups.</p></div><span class="badge">${db.orders.length} farmer orders · ${pending.length} pickups</span></div>${db.submissions.length?`<section class="card pad" style="margin-bottom:18px"><div class="section-head"><h2>Generator pickup requests</h2><span class="badge orange">${pending.length} open</span></div><div class="list">${db.submissions.map(s=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${esc(s.generator)} · ${s.qty.toLocaleString()} kg of unsorted organic waste</strong><small>${esc(s.location)} · ${esc(s.phone)} · ${esc(s.date)}</small></div><span class="badge ${s.status==='Submitted'?'orange':s.status==='Collected'?'':'blue'}">${esc(s.status)}</span>${!['Collected','Verified','Cancelled'].includes(s.status)?`<button class="btn btn-soft" data-generator-review="${s.id}">Track pickup</button>`:''}</div>`).join('')}</div></section>`:''}<div class="toolbar"><label class="searchbar">${icon('search')}<input placeholder="Search order or farmer"></label><div class="toolbar-group"><select class="select"><option>All statuses</option><option>Order received</option><option>Confirmed</option><option>On the way</option></select></div></div><section class="card table-wrap"><table class="table"><thead><tr><th>Order</th><th>Farmer</th><th>Supplies</th><th>Order total</th><th>Date</th><th>Status</th><th>Update</th></tr></thead><tbody>${db.orders.length?db.orders.map(o=>`<tr><td><strong>${o.id}</strong></td><td>${esc(o.receiverName||'Farmer')}<br><small class="muted">${esc(o.address||'')}</small></td><td>${o.items.map(i=>`${i.qty}× ${esc(i.name)}`).join('<br>')}</td><td><strong>${money(o.total)}</strong></td><td>Placed ${o.date}<br><small class="muted">Deliver by ${esc(o.deliveryDate||'Not specified')}</small></td><td><span class="badge orange">${o.status}</td><td><select class="select" data-status="${o.id}">${['Order received','Confirmed','Preparing','On the way','Delivered','Cancelled'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''):`<tr><td colspan="7">No farmer orders yet.</td></tr>`}</tbody></table></section></div>`}
function agentsPage(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">People in the field</div><h1>Field agents</h1><p>Your collection network keeps quality supplies moving.</p></div><button class="btn btn-primary" data-action="invite-agent">${icon('person_add')} Add field agent</button></div><div class="grid waste-grid">${[['👩🏽‍🌾','Sarah Namusoke','Kampala Central','Active','14 collections','92% quality pass'],['👨🏿‍🌾','Peter Okello','Mukono & Jinja','On collection','9 collections','96% quality pass'],['👩🏾‍🌾','Grace Akello','Luwero District','Active','11 collections','95% quality pass']].map(a=>`<article class="card pad"><div style="display:flex;align-items:center;gap:12px"><div class="avatar" style="width:54px;height:54px;font-size:29px">${a[0]}</div><div style="flex:1"><h3 style="margin:0">${a[1]}</h3><span class="muted tiny">${icon('location_on')} ${a[2]}</span></div><span class="badge ${a[3]==='Active'?'':'orange'}">${a[3]}</span></div><div class="grid" style="grid-template-columns:1fr 1fr;margin:20px 0"><div><strong>${a[4]}</strong><div class="muted tiny">This month</div></div><div><strong>${a[5]}</strong><div class="muted tiny">Quality rating</div></div></div><div class="agent-card-actions" style="display:flex;gap:8px"><button class="btn btn-soft" style="flex:1" data-action="call-agent">${icon('call')} Call agent</button><button class="btn btn-outline" data-action="agent-history">${icon('history')} History</button></div></article>`).join('')}</div><section class="card pad" style="margin-top:20px"><div class="section-head"><h2>Collection coverage</h2><span class="badge">3 regions active</span></div><div class="map-card" style="height:280px"><div class="map-road"></div><div class="map-pin" style="left:33%;top:35%">${icon('recycling')}</div><div class="map-pin" style="left:56%;top:54%;background:var(--green)">${icon('recycling')}</div><div class="map-pin" style="left:72%;top:32%;background:#3978a4">${icon('recycling')}</div><span class="map-caption">Kampala · Mukono · Luwero</span></div></section></div>`}
function render(){let r=route();if(r.startsWith('tracking/'))r='tracking';if(db.role==='generator'&&!['home','submissions','trackwaste','profile','notifications'].includes(r)){go('home');return}if(r==='market'||r==='category'||r.startsWith('product/')){go('cart');return}if(!db.role&&['tracking','profile','confirmation'].includes(r)){go('home');loginPrompt();return}let page=r==='notifications'?notificationsPage:(db.role==='generator'?{home:generatorHome,submissions:generatorSubmissions,trackwaste:generatorTracking,profile}: {home,cart:cartPage,confirmation,orders:favoritesPage,favorites:favoritesPage,tracking,profile:db.role==='staff'?staffProfile:profile,staff:staffHome,inventory:inventoryPage,collection:collectionPage,stafforders:staffOrders,agents:agentsPage})[r]||home;let markup=page();if(r==='cart'&&db.role==='farmer')markup=markup.replace(/<\/div>$/,`${orderHistoryPanel()}</div>`);shell(markup);if(r==='home'&&db.role==='farmer')setTimeout(maybePromptInstall,650)}
function maybePromptInstall(){if(installPromptShown||route()!=='home'||db.role!=='farmer'||!matchMedia('(max-width:760px)').matches||matchMedia('(display-mode: standalone)').matches||navigator.standalone)return;try{if(localStorage.getItem('gdfa-install-prompt-shown')==='1')return;localStorage.setItem('gdfa-install-prompt-shown','1')}catch{}installPromptShown=true;const ios=/iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);const instructions=ios?`<div class="install-steps"><span>1</span><p>Tap <strong>Share</strong> in Safari.</p><span>2</span><p>Choose <strong>Add to Home Screen</strong>, then tap <strong>Add</strong>.</p></div>`:'';const m=openModal(ios?'Add ECO MARKET CONNECT to your Home Screen':'Install ECO MARKET CONNECT',`<div class="install-prompt"><div class="install-prompt-icon"><img src="pwa-icon.svg" alt=""></div><p class="install-prompt-copy">Get quicker access to your farm supplies, orders, and delivery updates.</p>${ios?instructions:`<p class="install-fallback" hidden>Open your browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</p>`}<div class="install-prompt-actions"><button class="btn btn-primary btn-block" id="install-app-now">${ios?'Got it':'Install app'}</button><button class="install-later" data-modal-close>Maybe later</button></div></div>`);m.querySelector('.modal').classList.add('install-modal');m.querySelector('#install-app-now').addEventListener('click',async()=>{if(ios){m.remove();return}if(installPromptEvent){const promptEvent=installPromptEvent;installPromptEvent=null;await promptEvent.prompt();await promptEvent.userChoice;m.remove();return}const fallback=m.querySelector('.install-fallback');fallback.hidden=false;m.querySelector('#install-app-now').textContent='Okay'});}
function openModal(title,body,submitLabel='Save'){const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<div class="modal"><div class="modal-head"><h2>${title}</h2><button class="close" data-modal-close>${icon('close')}</button></div>${body}</div>`;document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-modal-close]')){m.remove();return}if(e.target.closest('[data-action="signup"]')){m.remove();signupModal();return}if(e.target.closest('[data-action="existing-login"]')){m.remove();loginPage();return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;m.remove();render()}if(e.target.closest('[data-action="reset-sent"]')){m.remove();toast('Demo reset code sent!')}if(e.target.closest('[data-action="invite-sent"]')){m.remove();toast('Agent invitation created')}if(e.target.closest('[data-action="sample-confirm"]')){m.remove();toast('Sample order confirmed')}});return m}
function generatorReviewModal(id){const s=db.submissions.find(x=>x.id===id);if(!s)return;openModal('Generator pickup · '+s.id,`<p><strong>${esc(s.generator)}</strong> submitted ${s.qty.toLocaleString()} kg of unsorted organic waste.</p><p class="muted">${esc(s.location)} · ${esc(s.phone)}</p><label class="field">Pickup status<select id="generator-status"><option>Submitted</option><option>Confirmed</option><option>On the way</option><option>Collected</option><option>Verified</option><option>Cancelled</option></select></label><button class="btn btn-primary btn-block" style="margin-top:15px" data-generator-save="${s.id}">Save pickup status</button>`)}
function listingModal(id){let w=db.inventory.find(x=>x.id===id)||{name:'Sorted organic waste',price:'',stock:'',location:'',emoji:'♻️',color:'vegetable',unit:'50 kg sack'};let m=openModal(id?'Edit sorted stock':'Add sorted organic waste stock',`<form id="listing-form"><div class="form-grid"><label class="field full">Stock name<input name="name" value="${esc(w.name)}" required></label><label class="field">Price per sack (UGX)<input type="number" name="price" value="${w.price}" required></label><label class="field">Available quantity (kg)<input type="number" name="stock" value="${w.stock}" required></label><label class="field full">Collection location<input name="location" value="${esc(w.location)}" required></label><label class="field">Availability<select name="fresh"><option>Collected today</option><option>Collected yesterday</option><option>Collected 2 days ago</option></select></label><div class="field full"><button class="btn btn-primary btn-block">${icon('save')} Save sorted stock</button></div></div></form>`);m.querySelector('#listing-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),data={id:'w1',name:'Sorted organic waste',category:'Sorted organic waste',price:+f.get('price'),stock:+f.get('stock'),location:f.get('location'),emoji:'♻️',fresh:f.get('fresh'),color:'vegetable',unit:'50 kg sack'};if(id)Object.assign(w,data);else{db.inventory[0].stock+=data.stock;db.inventory[0].location=data.location;db.inventory[0].fresh=data.fresh}save();m.remove();render();toast('Sorted organic waste stock saved')};}
function signupModal(){let m=openModal('Create your farmer account',`<p class="muted">Create an account to place and track your order.</p><form id="signup-form"><div class="signup-photo-row"><div class="signup-photo-preview" id="signup-photo-preview">👩🏽‍🌾</div><label class="signup-photo-picker">Choose profile photo<input id="signup-photo-file" name="photo" type="file" accept="image/*"><small>JPG or PNG · optional</small></label></div><div class="form-grid"><label class="field">Full name<input name="name" placeholder="Your name" required></label><label class="field">Phone number<input name="phone" placeholder="+256 700 000 000" required></label><label class="field">Password<input name="password" type="password" minlength="6" autocomplete="new-password" required></label><label class="field">Farm / business name<input name="farm" placeholder="Your farm name"></label><label class="field">Farm type<select name="farmType"><option>Black Soldier Fly (BSF)</option><option>Other livestock</option></select></label><label class="field full">Farm location<input name="location" placeholder="District, region" required></label><div class="field full"><button class="btn btn-primary btn-block">Create account ${icon('arrow_forward')}</button></div></div><div class="auth-foot" style="text-align:center;margin-top:12px">Already registered? <button type="button" class="text-link" data-action="existing-login">Sign in</button></div></form>`);m.querySelector('#signup-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),phone=String(f.get('phone')).trim();if(db.accounts.some(a=>a.phone===phone)){toast('An account already uses that phone number. Please sign in.');return}const photo=await (e.target.elements.photo.files[0]?compressAvatar(e.target.elements.photo.files[0]):null);db.user={name:f.get('name'),title:`BSF farmer · ${f.get('location')||'New member'}`,avatar:'👩🏽‍🌾',photo,phone,farm:f.get('farm'),farmType:f.get('farmType'),location:f.get('location')};db.accounts.push({phone,password:f.get('password'),user:db.user});db.role='farmer';save();m.remove();go('home');toast('Your farmer account is ready!');if(pendingOrder)completeOrder(pendingOrder)};}
function loginPrompt(){openModal('Sign in to place your order',`<p class="muted">Create an account to save your details and track future orders. Already have an account? Sign in to continue.</p><div class="grid" style="gap:10px"><button class="btn btn-primary btn-block" data-action="signup">Create farmer account</button><button class="btn btn-outline btn-block" data-action="existing-login">I already have an account</button></div>`)}
function compressAvatar(file){return new Promise(resolve=>{const reader=new FileReader();reader.onerror=()=>resolve(null);reader.onload=()=>{const img=new Image();img.onerror=()=>resolve(null);img.onload=()=>{const scale=Math.min(1,320/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82))};img.src=reader.result};reader.readAsDataURL(file)})}
app.addEventListener('click',e=>{let el=e.target.closest('[data-onboarding-dot],[data-onboarding],[data-product-qty],[data-favorite],[data-order-filter],[data-promo-index],[data-home-result],[data-go],[data-filter],[data-set-filter],[data-add],[data-qty],[data-remove],[data-edit],[data-action],[data-order-status],[data-generator-review],[data-generator-save]');if(!el)return;if(el.dataset.onboardingDot!==undefined){onboardingStep=Number(el.dataset.onboardingDot);renderOnboarding();return}if(el.dataset.onboarding==='skip'){finishOnboarding();return}if(el.dataset.onboarding==='back'){onboardingStep=Math.max(0,onboardingStep-1);renderOnboarding();return}if(el.dataset.onboarding==='next'){if(onboardingStep<onboardingSlides.length-1){onboardingStep++;renderOnboarding()}else finishOnboarding();return}if(el.dataset.favorite){const id=el.dataset.favorite;db.favorites.includes(id)?db.favorites=db.favorites.filter(x=>x!==id):db.favorites.push(id);save();render();toast(db.favorites.includes(id)?'Added to favorites':'Removed from favorites');return}if(el.dataset.productQty){const input=$('#product-qty');if(input)input.value=Math.max(1,(Number(input.value)||1)+(el.dataset.productQty==='inc'?1:-1));return}if(el.dataset.orderFilter){orderFilter=el.dataset.orderFilter;render();return}if(el.dataset.promoIndex!==undefined){const root=el.closest('.farmer-promo');if(root){const idx=Number(el.dataset.promoIndex);root.querySelectorAll('[data-promo-slide]').forEach((x,n)=>{x.classList.toggle('active',n===idx);x.setAttribute('aria-hidden',n===idx?'false':'true')});root.querySelectorAll('[data-promo-index]').forEach((x,n)=>{x.classList.toggle('active',n===idx);x.setAttribute('aria-current',n===idx?'true':'false')})}return}if(el.dataset.homeResult){let item=db.inventory.find(w=>w.id===el.dataset.homeResult);search=item?.name||'';filter='All';go(item?`product/${item.id}`:'market');return}if(el.dataset.go){if(!db.role&&['tracking','profile','confirmation'].includes(el.dataset.go)){loginPrompt();return}go(el.dataset.go);return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.setFilter){filter=el.dataset.setFilter;search='';if(route()==='category')render();else render();return}if(el.dataset.add){if(!db.role){loginPrompt();return}const amount=Math.max(1,Number($('#product-qty')?.value||el.dataset.addQty)||1);let x=db.cart.find(c=>c.id===el.dataset.add);if(x)x.qty+=amount;else db.cart.push({id:el.dataset.add,qty:amount});save();toast('Added to your order');render();return}if(el.dataset.qty){let c=db.cart.find(x=>x.id===el.dataset.qty);if(c){c.qty+=+el.dataset.delta;if(c.qty<1)db.cart=db.cart.filter(x=>x.id!==c.id)}save();render();return}if(el.dataset.remove){db.cart=db.cart.filter(x=>x.id!==el.dataset.remove);save();render();return}if(el.dataset.edit){listingModal(el.dataset.edit);return}if(el.dataset.generatorReview){generatorReviewModal(el.dataset.generatorReview);return}if(el.dataset.generatorSave){const s=db.submissions.find(x=>x.id===el.dataset.generatorSave),status=$('#generator-status')?.value;if(s&&status){s.status=status;if((status==='Collected'||status==='Verified')&&!s.stockAdded){const match=db.inventory[0];match.stock+=s.qty;match.fresh='Collected today';s.stockAdded=true;db.collections.unshift({id:'COL-'+Date.now().toString().slice(-4),type:'Sorted organic waste',qty:s.qty,agent:s.generator,place:s.location,date:new Date().toLocaleString('en-UG',{weekday:'short',hour:'numeric',minute:'2-digit'}),status:'Added to stock'});}save();document.querySelectorAll('.modal-backdrop').forEach(m=>m.remove());render();notifyUser(status==='Collected'||status==='Verified'?'Waste pickup complete':'Pickup status updated',status==='Verified'?'Staff verified your collected waste and added it to available stock.':status==='Collected'?'Staff collected your waste and updated available stock.':`Your pickup is now ${status.toLowerCase()}.`)}return}if(el.dataset.orderStatus){let o=db.orders.find(x=>x.id===el.dataset.orderStatus);if(o)advance(o);return}let a=el.dataset.action;if(a==='place-order'){if(!db.role){loginPrompt();return}placeOrder()}if(a==='clear-cart'){db.cart=[];save();render()}if(a==='new-listing')listingModal();if(a==='submit-waste')submitWasteModal();if(a==='signup'){document.querySelectorAll('.modal-backdrop').forEach(x=>x.remove());signupModal()}if(a==='existing-login'){document.querySelectorAll('.modal-backdrop').forEach(x=>x.remove());loginPage()}if(a==='logout'){db.role=null;db.user=null;save();loginPage()}if(a==='menu')toast('Use the navigation tabs to move around the demo');if(a==='notifications'){go('notifications')}if(a==='help')openModal('We’re here to help',`<p>Our farmer support team is ready to help with supplies, orders, or deliveries.</p><div class="list-row"><div class="list-icon">${icon('call')}</div><div class="row-main"><strong>Call ECO MARKET CONNECT</strong><small>+256 700 123 456 · Mon–Sat, 8am–6pm</small></div></div><div class="list-row"><div class="list-icon">${icon('mail')}</div><div class="row-main"><strong>Email our team</strong><small>hello@greendivert.africa</small></div></div>`);if(a==='forgot')openModal('Reset your password',`<p class="muted">Enter your phone number and we’ll help you get back in.</p><label class="field">Phone number<input placeholder="+256 700 123 456"></label><button class="btn btn-primary btn-block" style="margin-top:15px" data-action="reset-sent">Send reset code</button>`);if(a==='avatar')toast('Avatar picker is ready in the full account build');if(a==='save-profile'){const name=$('#profile-name')?.value.trim();if(name)db.user.name=name;save();render();toast('Your farm profile has been saved')}if(a==='invite-agent')openModal('Add a field agent',`<div class="form-grid"><label class="field">Agent name<input placeholder="Full name"></label><label class="field">Phone number<input placeholder="+256 700 000 000"></label><label class="field full">Assigned area<input placeholder="District or collection zone"></label><button class="btn btn-primary field full" data-action="invite-sent">Send invitation</button></div>`);if(a==='call-agent')toast('Call +256 700 123 456');if(a==='agent-history')openModal('Agent collection history',`<div class="list">${db.collections.map(c=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${c.type} · ${c.qty} kg</strong><small>${c.agent} · ${c.place} · ${c.date}</small></div></div>`).join('')}</div>`);if(a==='export')toast('Inventory report prepared for this demo');if(a==='filters')openModal('Filter marketplace supplies',`<div class="list">${['All'].map(x=>`<button class="side-link" data-filter="${x}">${icon('filter_list')}${x}</button>`).join('')}</div>`);if(a==='sample-order')openModal('Sample order · GD-48291',`<div class="order-banner"><strong>David Kato · Wakiso</strong><span class="badge orange">Needs confirmation</span></div><p>4× Banana peels · 2× Vegetable mix<br><strong>UGX 350,000</strong></p><button class="btn btn-primary btn-block" data-action="sample-confirm">Confirm this sample order</button>`);});
function reserveOrderStock(o){if(o.stockDeducted)return true;for(const item of o.items){const stock=db.inventory.find(w=>w.id===item.id)||db.inventory.find(w=>w.name===item.name);const amount=item.unit==='kg'?item.qty:item.qty*50;if(!stock||amount>stock.stock)return false}for(const item of o.items){const stock=db.inventory.find(w=>w.id===item.id)||db.inventory.find(w=>w.name===item.name);stock.stock-=item.unit==='kg'?item.qty:item.qty*50}o.stockDeducted=true;return true}
function advance(o){let steps=['Order received','Confirmed','Preparing','On the way','Delivered'],next=Math.min(4,(o.progress||0)+1);if(next===1&&!reserveOrderStock(o)){toast('There is not enough stock left to confirm this order.');return}o.progress=next;o.status=steps[o.progress];save();render();notifyUser('Order status updated',`Order ${o.id}: ${o.status}.`)}
app.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();const f=new FormData(e.target),identity=String(f.get('identity')||'').trim(),account=db.accounts.find(a=>a.phone===identity&&a.password===f.get('password'));if(!account){toast('We couldn’t find an account with those details. Please check them or create an account.');return}db.role='farmer';db.user=account.user;save();const order=pendingOrder;go('home');toast(`Welcome ${db.user.name.split(' ')[0]}!`);if(order)completeOrder(order)}if(e.target.id==='generator-submit-form'){e.preventDefault();const f=new FormData(e.target),qty=Number(f.get('qty'));if(!Number.isFinite(qty)||qty<=0){toast('Enter a waste amount greater than zero.');return}const submission={id:'GEN-'+Date.now().toString().slice(-6),type:'Unsorted organic waste',generator:db.user.name,qty,contact:String(f.get('contact')).trim(),phone:String(f.get('phone')).trim(),alternatePhone:String(f.get('alternatePhone')||'').trim(),location:String(f.get('location')).trim(),pickupDate:String(f.get('pickupDate')||''),pickupTime:String(f.get('pickupTime')||'Any time'),condition:String(f.get('condition')||''),notes:String(f.get('notes')||'').trim(),date:new Date().toLocaleString('en-UG',{weekday:'short',hour:'numeric',minute:'2-digit'}),status:'Submitted',stockAdded:false};db.submissions.unshift(submission);save();document.querySelectorAll('.modal-backdrop').forEach(m=>m.remove());if(db.role==='generator')go('submissions');else render();notifyUser('Waste submitted successfully',`Your ${qty.toLocaleString()} kg unsorted organic waste pickup request was submitted successfully.`);return}if(e.target.id==='order-form'){e.preventDefault();if(!e.target.reportValidity())return;const details=collectOrderForm(e.target);if(details)placeOrder(details)}if(e.target.matches('[data-profile-form]')){e.preventDefault();if(!e.target.reportValidity())return;const f=new FormData(e.target),oldPhone=db.user.phone,phone=String(f.get('phone')||'').trim();if(db.accounts.some(a=>a.phone===phone&&a.phone!==oldPhone)){toast('That phone number is already linked to another account.');return}const oldName=db.user.name;db.user={...db.user,name:String(f.get('name')||'').trim(),phone,email:String(f.get('email')||'').trim(),farm:String(f.get('farm')||'').trim(),farmType:f.get('farmType'),location:String(f.get('location')||'').trim(),photo:e.target.dataset.photo||db.user.photo};db.user.title=db.role==='generator'?'Community waste generator':`BSF farmer · ${db.user.location||'Farmer'}`;if(db.role==='generator')db.submissions.forEach(s=>{if(s.generator===oldName){s.phone=db.user.phone;s.contact=db.user.name;s.location=db.user.location}});const account=db.accounts.find(a=>a.phone===oldPhone);if(account){account.phone=phone;account.user={...db.user}}save();render();toast(db.role==='generator'?'Your generator profile has been saved':'Your profile and delivery details have been saved')}if(e.target.id==='collection-form'){e.preventDefault();let f=new FormData(e.target),w=db.inventory[0],qty=+f.get('qty'),passed=f.get('quality').startsWith('Passed');if(passed)w.stock+=qty;let date=new Date().toLocaleString('en-UG',{weekday:'short',hour:'numeric',minute:'2-digit'});db.collections.unshift({id:'COL-'+Date.now().toString().slice(-4),type:passed?'Sorted organic waste':'Unsorted organic waste',qty,agent:f.get('agent'),place:f.get('place'),date,status:passed?'Added to stock':'Awaiting review'});save();render();notifyUser('Collection saved',`Collection logged${passed?' and added to sorted stock':' as unsorted waste for review'}.`)}});
app.addEventListener('input',e=>{if(e.target.matches('[data-order-qty]')||e.target.matches('[data-order-unit]')){const form=e.target.form,input=form?.querySelector('[data-order-qty="total"]'),unit=form?.querySelector('[data-order-unit]')?.value||'kg',cap=Number(input?.dataset.stock)||0,entered=Number(input?.value)||0,kg=unit==='ton'?entered*1000:entered;if(input&&kg>cap){input.value=unit==='ton'?String(cap/1000):String(cap)}const estimate=form&&$('#order-estimate');if(estimate){const finalQty=Number(input?.value)||0,items=allocateOrderQuantity(unit==='ton'?finalQty*1000:finalQty),subtotal=(items||[]).reduce((sum,item)=>sum+item.price,0);estimate.textContent=money(Math.round(subtotal+(subtotal?15000:0)));const subtotalEl=$('#order-subtotal');if(subtotalEl)subtotalEl.textContent=money(Math.round(subtotal))}}if(e.target.id==='home-search'){search=e.target.value;let box=$('#home-search-results');if(box)box.innerHTML=homeSearchResults(search)}if(['market-search','market-search-mobile'].includes(e.target.id)){search=e.target.value;let pos=e.target.selectionStart;let items=db.inventory.filter(w=>(filter==='All')&&(`${w.name} ${w.location}`).toLowerCase().includes(search.toLowerCase()));let content=items.length?items.map(wasteCard).join(''):`<div class="empty card" style="grid-column:1/-1">No supplies match that search.</div>`;let grid=$('#market-grid');if(grid)grid.innerHTML=content;let mobileGrid=$('#market-grid-mobile');if(mobileGrid)mobileGrid.innerHTML=items.length?items.map(categoryProductCard).join(''):`<div class="category-empty"><strong>No matching supplies</strong><span>Try a different search or category.</span></div>`;e.target.focus();e.target.setSelectionRange(pos,pos)}if(e.target.id==='inventory-search'){let items=db.inventory.filter(w=>w.name.toLowerCase().includes(e.target.value.toLowerCase()));$('#inventory-body').innerHTML=inventoryRows(items)}});
app.addEventListener('change',e=>{if(e.target.id==='signup-photo-file'&&e.target.files[0]){const file=e.target.files[0],preview=$('#signup-photo-preview');if(file.type.startsWith('image/')&&preview){preview.innerHTML=`<img src="${URL.createObjectURL(file)}" alt="Selected profile photo">`}}});
app.addEventListener('change',async e=>{if(e.target.matches('[data-profile-photo]')&&e.target.files[0]){const form=e.target.closest('[data-profile-form]'),photo=await compressAvatar(e.target.files[0]);if(photo&&form){form.dataset.photo=photo;const preview=form.querySelector('.profile-photo-preview');if(preview)preview.innerHTML=`<img class="avatar-image" src="${photo}" alt="Profile photo preview">`}}});
app.addEventListener('change',e=>{if(['sort-select','sort-select-mobile'].includes(e.target.id)){ if(e.target.value==='price')db.inventory.sort((a,b)=>a.price-b.price);if(e.target.value==='stock')db.inventory.sort((a,b)=>b.stock-a.stock);render()}if(e.target.id==='stock-filter'){let items=db.inventory.filter(w=>e.target.value==='Low stock'?w.stock<250:e.target.value==='In stock'?w.stock>=250:true);$('#inventory-body').innerHTML=inventoryRows(items)}if(e.target.dataset.status){let o=db.orders.find(x=>x.id===e.target.dataset.status);if(o){const nextStatus=e.target.value;if(nextStatus==='Confirmed'&&!reserveOrderStock(o)){e.target.value=o.status;toast('There is not enough stock left to confirm this order.');return}o.status=nextStatus;o.progress=['Order received','Confirmed','Preparing','On the way','Delivered'].indexOf(o.status);save();render();toast(`Order ${o.id} updated`)}}});
window.startDemo=login;window.addEventListener('hashchange',render);if(!location.hash)history.replaceState(null,'','#'+(db.role==='staff'?'staff':'home'));startExperience();
 
